mapper.sql:
r.status = '0' and r.total_score is not null
 and r.questionnaire_id = #{questionnaireId}
 and q.semester_id = #{semesterId}

mapper.select:
select cl.class_id as classId, cl.class_name as className, count(1) as totalCount, coalesce(round(avg(),2),0) as avgScore from aem_evaluation_result r left join aem_evaluation_questionnaire q on r.questionnaire_id = q.questionnaire_id left join sam_student s on s.student_id = r.student_id left join brm_class cl on cl.class_id = s.class_id
r.status = '0' and r.total_score is not null and s.class_id is not null and r.questionnaire_id = #{questionnaireId} and q.semester_id = #{semesterId} and r.course_id = #{courseId}
group by cl.class_id, cl.class_name order by avgScore desc

select date_format(r.eval_date, '%Y-%m') as month, count(1) as totalCount, coalesce(round(avg(),2),0) as avgScore from aem_evaluation_result r left join aem_evaluation_questionnaire q on r.questionnaire_id = q.questionnaire_id
r.status = '0' and r.total_score is not null and r.eval_date is not null and r.questionnaire_id = #{questionnaireId}
group by date_format(r.eval_date, '%Y-%m') order by month asc

select r.comment
from aem_evaluation_result r

    r.status = '0' and r.comment is not null and trim(r.comment) <> ''
     and r.teacher_id = #{teacherId}
     and r.course_id = #{courseId}
     and r.questionnaire_id = #{questionnaireId}

order by r.eval_date desc
limit 500
